#include <cmath>
#define main hecbench_original_main
#include "sortKV-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
template<class T>double study(int n,int repeat,std::vector<double>&values,std::vector<double>&expected){std::vector<int>inputkeys(n),outkeys(n);std::vector<T>inputvals(n),outvals(n);for(int i=0;i<n;i++){inputkeys[i]=(i*2053)%n;inputvals[i]=T(inputkeys[i]%256);expected.push_back(i);}for(int i=0;i<n;i++)expected.push_back(i%256);thrust::device_vector<int>keys(n);thrust::device_vector<T>vals(n);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++){cudaMemcpy(thrust::raw_pointer_cast(keys.data()),inputkeys.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(thrust::raw_pointer_cast(vals.data()),inputvals.data(),n*sizeof(T),cudaMemcpyHostToDevice);thrust::sort_by_key(keys.begin(),keys.end(),vals.begin());cudaMemcpy(outkeys.data(),thrust::raw_pointer_cast(keys.data()),n*4,cudaMemcpyDeviceToHost);cudaMemcpy(outvals.data(),thrust::raw_pointer_cast(vals.data()),n*sizeof(T),cudaMemcpyDeviceToHost);}cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;for(int v:outkeys)values.push_back(v);for(T v:outvals)values.push_back(double(v));return seconds;}
void run_study(int n,int repeat,int trial){std::vector<double>values,expected;double total=0;total+=study<unsigned char>(n,repeat,values,expected);total+=study<short>(n,repeat,values,expected);total+=study<int>(n,repeat,values,expected);total+=study<long>(n,repeat,values,expected);if(trial)emit(trial,total,values,expected,repeat);}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):1024,repeat=argc>2?atoi(argv[2]):3;run_study(n,1,0);for(int trial=1;trial<=5;trial++)run_study(n,repeat,trial);return 0;}
